import 'server-only'
import {
  PDFDocument,
  PDFImage,
  StandardFonts,
  rgb,
  type PDFFont,
  type PDFPage,
} from 'pdf-lib'

/**
 * Server-side signed-PDF rendering for the tenant portal flow (M3 #6 / S3b
 * of the Lovable port). Loads the existing report PDF (generated by the
 * jspdf-based pipeline today; will eventually move server-side too) and
 * appends a clean signature page bearing all three parties' signatures:
 *
 *   - Clerk    — image (PNG/JPG) from `inspection_reports.clerk_signature_url`
 *   - Client   — image (PNG/JPG) from `jobs.client_signature_url`
 *   - Tenant   — typed name from `generated_reports.tenant_signature` rendered
 *                in a script-like style (italic) with the timestamp underneath
 *
 * The output is the *new* PDF bytes; the caller uploads them to a fresh key
 * in the `generated-reports` bucket and updates `generated_reports.report_url`
 * to the new key. The original PDF is **retained at its original key** for
 * audit trail (M3 #7 supersede + retain).
 */

export type SignaturePartyImage = {
  bytes: Uint8Array
  /** Hint at content-type; if absent or unknown we sniff the bytes. */
  contentType?: string | null
}

export type SignedPdfInputs = {
  /** Bytes of the original report PDF as fetched from storage. */
  originalPdfBytes: Uint8Array | ArrayBuffer
  /** Display label for the report — usually job ref + address. */
  reportLabel: string
  /** Inspection type, surfaced on the signature page header. */
  inspectionTypeLabel: string

  clerk: SignaturePartyImage | null
  client: SignaturePartyImage | null
  /** 0040 — the tenant's adopted mark. Null for reports signed before
   *  adopt-a-signature existed, which still render the typed name. */
  tenant: SignaturePartyImage | null

  tenantTypedName: string
  tenantSignedAt: Date
}

const SIGNATURE_BOX_WIDTH = 240
const SIGNATURE_BOX_HEIGHT = 80
const COLUMN_X_LEFT = 60
const COLUMN_X_RIGHT_GAP = 40

/**
 * Append a signature page to the supplied PDF and return the bytes.
 *
 * If a party's image fails to embed (corrupt bytes, unsupported format),
 * we fall back to drawing a labelled "(signature on file)" placeholder
 * rather than failing the whole re-render — the audit/forensic record is
 * still on the report row + audit_events.
 */
export async function appendSignaturePage(
  inputs: SignedPdfInputs
): Promise<Uint8Array> {
  const pdf = await PDFDocument.load(inputs.originalPdfBytes)
  const helv = await pdf.embedFont(StandardFonts.Helvetica)
  const helvBold = await pdf.embedFont(StandardFonts.HelveticaBold)
  const helvItalic = await pdf.embedFont(StandardFonts.HelveticaOblique)

  const page = pdf.addPage()
  const { width, height } = page.getSize()

  // Header
  page.drawText('Signatures', {
    x: 60,
    y: height - 80,
    size: 24,
    font: helvBold,
    color: rgb(0.1, 0.1, 0.1),
  })
  page.drawText(inputs.reportLabel, {
    x: 60,
    y: height - 105,
    size: 11,
    font: helv,
    color: rgb(0.4, 0.4, 0.4),
  })
  page.drawText(inputs.inspectionTypeLabel, {
    x: 60,
    y: height - 122,
    size: 10,
    font: helv,
    color: rgb(0.5, 0.5, 0.5),
  })

  // Three signature blocks stacked top→bottom.
  const startY = height - 180
  const blockSpacing = SIGNATURE_BOX_HEIGHT + 60

  await drawImageSignatureBlock(pdf, page, helv, helvBold, {
    label: 'Clerk',
    image: inputs.clerk,
    x: COLUMN_X_LEFT,
    y: startY,
  })

  await drawImageSignatureBlock(pdf, page, helv, helvBold, {
    label: 'Client',
    image: inputs.client,
    x: COLUMN_X_LEFT,
    y: startY - blockSpacing,
  })

  // Tenant: the adopted mark where one exists, falling back to the typed
  // name for reports signed before 0040. Either way the typed name and
  // timestamp are printed underneath — the mark is the signature, the
  // name is the identity, and a signature page that showed only a
  // squiggle would be worth less in a dispute than one showing both.
  if (inputs.tenant) {
    await drawImageSignatureBlock(pdf, page, helv, helvBold, {
      label: 'Tenant',
      image: inputs.tenant,
      x: COLUMN_X_LEFT,
      y: startY - blockSpacing * 2,
    })
    drawSignatureCaption(page, helv, {
      text: `${inputs.tenantTypedName} · ${formatTimestamp(inputs.tenantSignedAt)}`,
      x: COLUMN_X_LEFT,
      y: startY - blockSpacing * 2,
    })
  } else {
    drawTypedSignatureBlock(page, helv, helvBold, helvItalic, {
      label: 'Tenant',
      typedName: inputs.tenantTypedName,
      timestamp: inputs.tenantSignedAt,
      x: COLUMN_X_LEFT,
      y: startY - blockSpacing * 2,
    })
  }

  // Footer disclaimer
  page.drawText(
    'This signature page is appended on report sign-off. Original PDF retained for audit trail.',
    {
      x: 60,
      y: 60,
      size: 8,
      font: helv,
      color: rgb(0.55, 0.55, 0.55),
      maxWidth: width - 120,
    }
  )

  return pdf.save()
}

async function drawImageSignatureBlock(
  pdf: PDFDocument,
  page: PDFPage,
  helv: PDFFont,
  helvBold: PDFFont,
  block: {
    label: string
    image: SignaturePartyImage | null
    x: number
    y: number
  }
) {
  page.drawText(block.label, {
    x: block.x,
    y: block.y + SIGNATURE_BOX_HEIGHT + 10,
    size: 11,
    font: helvBold,
    color: rgb(0.1, 0.1, 0.1),
  })

  // Box outline
  page.drawRectangle({
    x: block.x,
    y: block.y,
    width: SIGNATURE_BOX_WIDTH,
    height: SIGNATURE_BOX_HEIGHT,
    borderColor: rgb(0.85, 0.85, 0.85),
    borderWidth: 0.6,
  })

  if (!block.image) {
    page.drawText('No signature on file', {
      x: block.x + 10,
      y: block.y + SIGNATURE_BOX_HEIGHT / 2 - 4,
      size: 10,
      font: helv,
      color: rgb(0.65, 0.65, 0.65),
    })
    return
  }

  let img: PDFImage | null = null
  try {
    img = await embedImage(pdf, block.image)
  } catch {
    img = null
  }
  if (!img) {
    page.drawText('(signature on file : could not embed)', {
      x: block.x + 10,
      y: block.y + SIGNATURE_BOX_HEIGHT / 2 - 4,
      size: 9,
      font: helv,
      color: rgb(0.65, 0.65, 0.65),
    })
    return
  }

  // Fit the image inside the box, preserving aspect ratio.
  const padding = 6
  const usableW = SIGNATURE_BOX_WIDTH - padding * 2
  const usableH = SIGNATURE_BOX_HEIGHT - padding * 2
  const ratio = Math.min(usableW / img.width, usableH / img.height, 1)
  const w = img.width * ratio
  const h = img.height * ratio
  page.drawImage(img, {
    x: block.x + (SIGNATURE_BOX_WIDTH - w) / 2,
    y: block.y + (SIGNATURE_BOX_HEIGHT - h) / 2,
    width: w,
    height: h,
  })
}

/** Name + timestamp printed just under a drawn/adopted signature box. */
function drawSignatureCaption(
  page: PDFPage,
  helv: PDFFont,
  block: { text: string; x: number; y: number }
) {
  page.drawText(block.text, {
    x: block.x,
    y: block.y - 14,
    size: 8,
    font: helv,
    color: rgb(0.4, 0.4, 0.4),
  })
}

function drawTypedSignatureBlock(
  page: PDFPage,
  helv: PDFFont,
  helvBold: PDFFont,
  helvItalic: PDFFont,
  block: {
    label: string
    typedName: string
    timestamp: Date
    x: number
    y: number
  }
) {
  page.drawText(block.label, {
    x: block.x,
    y: block.y + SIGNATURE_BOX_HEIGHT + 10,
    size: 11,
    font: helvBold,
    color: rgb(0.1, 0.1, 0.1),
  })

  page.drawRectangle({
    x: block.x,
    y: block.y,
    width: SIGNATURE_BOX_WIDTH,
    height: SIGNATURE_BOX_HEIGHT,
    borderColor: rgb(0.85, 0.85, 0.85),
    borderWidth: 0.6,
  })

  // Typed name in italic, centred vertically.
  page.drawText(block.typedName, {
    x: block.x + 14,
    y: block.y + SIGNATURE_BOX_HEIGHT / 2 + 4,
    size: 18,
    font: helvItalic,
    color: rgb(0.05, 0.05, 0.05),
  })

  // Timestamp + "typed signature" disclaimer underneath the name.
  const ts = formatTimestamp(block.timestamp)
  page.drawText(`Typed signature · ${ts}`, {
    x: block.x + 14,
    y: block.y + 14,
    size: 8,
    font: helv,
    color: rgb(0.5, 0.5, 0.5),
  })
}

async function embedImage(
  pdf: PDFDocument,
  img: SignaturePartyImage
): Promise<PDFImage | null> {
  const ct = (img.contentType ?? '').toLowerCase()
  // Use the content-type hint when present; otherwise sniff the magic bytes.
  if (ct.includes('png') || hasPngSignature(img.bytes)) {
    return pdf.embedPng(img.bytes)
  }
  if (ct.includes('jpg') || ct.includes('jpeg') || hasJpgSignature(img.bytes)) {
    return pdf.embedJpg(img.bytes)
  }
  // Last-resort attempt as PNG; pdf-lib throws on mismatch which the caller
  // catches and renders the fallback "(signature on file)" placeholder.
  return pdf.embedPng(img.bytes)
}

function hasPngSignature(bytes: Uint8Array): boolean {
  return (
    bytes.length >= 8 &&
    bytes[0] === 0x89 &&
    bytes[1] === 0x50 &&
    bytes[2] === 0x4e &&
    bytes[3] === 0x47
  )
}

function hasJpgSignature(bytes: Uint8Array): boolean {
  return bytes.length >= 3 && bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff
}

function formatTimestamp(d: Date): string {
  return d.toLocaleString('en-GB', {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    timeZone: 'UTC',
    timeZoneName: 'short',
  })
}
